import json
from pathlib import Path

source = json.loads(Path('source.json').read_text())
drafts = {}

def add(number, proposed, reason, notes):
    assert number not in drafts
    drafts[number] = (proposed, reason, notes)

add('L171-1',
    "<p>Sauf disposition contraire, un décret en Conseil d'État fixe les modalités d'application du présent livre.</p>",
    "Réécriture à droit constant : la réserve est placée en tête et le décret en Conseil d'État devient le sujet de la phrase. Le champ demeure celui du livre Ier. Aucune réforme de fond.",
    "La réserve des dispositions contraires et le niveau du décret en Conseil d'État sont conservés. Les mesures de logement de policy.json ne modifient pas cette habilitation générale.")

add('L172-1',
    "<p>Les directives territoriales d'aménagement approuvées avant le 13 juillet 2010 demeurent en vigueur.</p><p>Les articles L. 172-2 à L. 172-5 leur sont applicables.</p>",
    "Réécriture à droit constant : le maintien en vigueur et le régime applicable sont formulés dans deux alinéas directs. Aucune réforme de fond ni extension aux directives approuvées après la date limite.",
    "La date du 13 juillet 2010 et le renvoi à l'ensemble des articles L. 172-2 à L. 172-5 sont conservés. Le régime distinct des directives adoptées après cette date relève de L. 172-7.")

add('L172-2',
    "<p>Lorsqu'elles précisent les modalités d'application des dispositions particulières au littoral et aux zones de montagne prévues aux chapitres Ier et II du titre II du présent livre, les dispositions des directives territoriales d'aménagement s'appliquent aux personnes et aux opérations qui y sont mentionnées.</p>",
    "Réécriture à droit constant : la condition tenant au contenu des directives est énoncée en tête, puis la règle d'application aux personnes et opérations est explicitée. Les protections du littoral et de la montagne sont conservées. Aucune réforme de fond.",
    "Conserver la portée du renvoi aux chapitres Ier et II du titre II du livre Ier et aux personnes et opérations qui y sont mentionnées. La note source, fondée sur l'article 7 de l'ordonnance n° 2020-745 du 17 juin 2020, prévoit l'application de ces dispositions aux schémas de cohérence territoriale, plans locaux d'urbanisme, documents en tenant lieu et cartes communales dont l'élaboration ou la révision est engagée à compter du 1er avril 2021. Cette règle temporelle reste attachée à la disposition ; elle n'est pas une date d'entrée en vigueur du projet de réforme.")

add('L172-3',
    "<p>L'adaptation des directives territoriales d'aménagement est possible dans les conditions définies à l'article L. 300-6-1 du code de l'urbanisme.</p>",
    "Réécriture à droit constant : la faculté d'adaptation est formulée directement, sans modifier les conditions auxquelles elle est soumise. Aucune réforme de fond.",
    "Le renvoi à L. 300-6-1 demeure intégral. Cette faculté ne crée ni procédure autonome ni dispense des conditions de cet article.")

add('L172-4',
    "<p>L'autorité administrative compétente de l'État peut modifier une directive territoriale d'aménagement si la modification ne porte pas atteinte à son économie générale.</p>"
    "<p>Cette autorité soumet le projet de modification à une enquête publique dans les conditions définies au chapitre III du titre II du livre Ier du code de l'environnement. Lorsque la modification concerne uniquement un ou plusieurs établissements publics de coopération intercommunale compétents en matière de plan local d'urbanisme, ou une ou plusieurs communes qui ne sont pas membres d'un tel établissement, l'enquête peut être limitée au territoire de ces établissements ou de ces communes.</p>"
    "<p>L'autorité administrative compétente de l'État soumet également le projet, pour avis, aux régions, aux départements, aux communes chefs-lieux d'arrondissement, ainsi qu'aux communes de plus de 20 000 habitants et aux groupements de communes compétents en matière d'aménagement de l'espace ou d'urbanisme intéressés, et aux comités de massifs. L'avis de chacun est réputé favorable s'il n'est pas intervenu dans un délai de trois mois à compter de sa saisine.</p>"
    "<p>À l'occasion de toute modification d'une directive territoriale d'aménagement approuvée avant le 13 juillet 2010, il peut être décidé de lui appliquer les dispositions régissant les directives territoriales d'aménagement et de développement durables.</p>",
    "Réécriture à droit constant : l'autorité de l'État devient le sujet des actes de modification et de consultation ; les conditions de limitation territoriale de l'enquête et de l'avis favorable tacite sont isolées. Les quatre alinéas et les destinataires des consultations sont maintenus. Aucune réforme de fond.",
    "Sont conservés l'absence d'atteinte à l'économie générale, le renvoi au code de l'environnement, le seuil strict de plus de 20 000 habitants, les trois mois à compter de la saisine et la date du 13 juillet 2010. La faculté du dernier alinéa ne devient pas une conversion automatique. Le renvoi de L. 172-5 aux modalités du présent article reste opérant.")

add('L172-5',
    "<p>Un décret en Conseil d'État peut supprimer une directive territoriale d'aménagement selon les modalités prévues à l'article L. 172-4.</p>",
    "Réécriture à droit constant : l'acte qui peut prononcer la suppression est placé en sujet, tout en conservant la faculté de suppression et sa procédure. Aucune réforme de fond.",
    "La suppression reste prononcée par décret en Conseil d'État selon les modalités de L. 172-4. Aucun effet de caducité ou d'abrogation automatique n'est ajouté.")

add('L172-6',
    "<p>L'élaboration des directives territoriales d'aménagement est poursuivie jusqu'à son terme lorsque l'État a engagé, avant le 13 juillet 2010, les études préalables et la concertation avec les collectivités territoriales.</p>",
    "Réécriture à droit constant : la poursuite de l'élaboration est rattachée explicitement aux deux démarches préalables engagées par l'État. Aucune réforme de fond.",
    "Les études préalables et la concertation doivent toutes deux avoir été engagées avant le 13 juillet 2010. La disposition historique est conservée sans ouvrir une nouvelle période d'élaboration ; l'adoption postérieure relève de L. 172-7.")

add('L172-7',
    "<p>Les dispositions des articles L. 102-4 à L. 102-11 relatives aux directives territoriales d'aménagement et de développement durables s'appliquent aux directives territoriales d'aménagement adoptées après le 13 juillet 2010.</p>",
    "Réécriture à droit constant : le régime applicable est placé en tête et la catégorie de directives concernée est formulée plus directement. Aucune réforme de fond.",
    "Le critère demeure l'adoption après le 13 juillet 2010, sans substitution d'une autre date ni inclusion du jour même. Le renvoi complet à L. 102-4 à L. 102-11 est conservé.")

add('L173-1',
    "<p>Les schémas de secteur approuvés avant le 24 mars 2014 demeurent en vigueur.</p><p>Les articles L. 173-2 et L. 173-3 leur sont applicables.</p>",
    "Réécriture à droit constant : le maintien des schémas et les textes qui les régissent sont exprimés dans deux alinéas directs. Aucune réforme de fond.",
    "La date d'approbation antérieure au 24 mars 2014 et les deux renvois sont conservés. Les schémas approuvés après cette date relèvent de la transition de L. 173-4.")

add('L173-2',
    "<p>Les schémas de secteur conservent les effets prévus à l'article L. 122-1-14 dans sa rédaction en vigueur avant le 24 mars 2014. Les dispositions applicables aux schémas de cohérence territoriale les régissent.</p>"
    "<p>Toutefois, si un schéma de secteur porte sur le territoire d'une seule commune ou d'un seul établissement public de coopération intercommunale, cette commune ou cet établissement exerce les compétences de l'établissement public prévu à l'article L. 143-16.</p>",
    "Réécriture à droit constant : la conservation des effets historiques est séparée du régime applicable et le titulaire des compétences est désigné expressément dans l'exception. Aucune réforme de fond.",
    "Le renvoi à L. 122-1-14 est historique : sa rédaction antérieure au 24 mars 2014 est expressément maintenue, sans remplacement par un article actuel. L. 143-16, vérifié dans le corpus, désigne les établissements chargés du schéma de cohérence territoriale ; l'exception reste limitée à une seule commune ou un seul EPCI.")

add('L173-3',
    "<p>Un schéma de secteur peut tenir lieu de plan local d'urbanisme intercommunal s'il porte sur le périmètre d'un établissement public de coopération intercommunale compétent en matière de plan local d'urbanisme, respecte les principes et objectifs des plans locaux d'urbanisme et comprend tous les documents constitutifs d'un plan local d'urbanisme intercommunal.</p>"
    "<p>Les documents constitutifs d'un plan local d'urbanisme, notamment le dispositif réglementaire opposable aux demandes d'autorisation d'urbanisme, sont intégrés selon la procédure de modification prévue à l'article L. 143-32.</p>"
    "<p>L'État, l'établissement public de coopération intercommunale et les personnes publiques associées mentionnées aux articles L. 132-7 à L. 132-9 examinent conjointement le projet de modification. Le procès-verbal de cette réunion est joint au dossier de l'enquête publique.</p>"
    "<p>Le schéma de secteur tient lieu de plan local d'urbanisme jusqu'à la prochaine révision du schéma de cohérence territoriale ou jusqu'à l'élaboration d'un plan local d'urbanisme intercommunal.</p>",
    "Réécriture à droit constant : les conditions cumulatives de substitution sont conservées, l'intégration des documents est formulée directement et les participants à l'examen conjoint deviennent les sujets de la phrase. Les quatre alinéas sont maintenus. Aucune réforme de fond.",
    "Conserver les renvois à L. 143-32 et à L. 132-7 à L. 132-9, le procès-verbal joint au dossier et les deux événements mettant fin à la substitution. L. 143-32 renvoie désormais à la procédure de modification des articles L. 143-33 à L. 143-36 ; l'articulation avec l'examen conjoint et l'enquête expressément prévus ici doit rester vérifiée lors des coordinations de procédure. Aucun remplacement automatique de ces garanties n'est proposé.")

add('L173-4',
    "<p>L'élaboration d'un schéma de secteur peut se poursuivre jusqu'à son approbation selon les dispositions applicables aux schémas de cohérence territoriale avant le 24 mars 2014, si l'établissement public porteur du schéma de cohérence territoriale a délimité son périmètre par délibération avant cette date.</p>"
    "<p>Toutefois, si le schéma de secteur porte sur le territoire d'une seule commune ou d'un seul établissement public de coopération intercommunale, l'enquête publique est organisée uniquement dans les communes comprises dans son périmètre.</p>"
    "<p>Après leur approbation, les schémas de secteur mentionnés au premier alinéa sont régis par les articles L. 173-2 et L. 173-3.</p>",
    "Réécriture à droit constant : la faculté de poursuivre l'élaboration est reliée à la délibération préalable ; la limitation géographique de l'enquête et le régime après approbation sont formulés séparément. Les trois alinéas sont conservés. Aucune réforme de fond.",
    "La délimitation par délibération, et non l'approbation, doit être antérieure au 24 mars 2014. La version historique des règles des SCoT est conservée jusqu'à l'approbation. Le renvoi au premier alinéa et ceux à L. 173-2 et L. 173-3 ne sont pas déplacés.")

add('L174-1',
    "<p>Sous réserve des articles L. 174-2 à L. 174-5, les plans d'occupation des sols qui n'ont pas été transformés en plans locaux d'urbanisme, en application du titre V du présent livre, au plus tard le 31 décembre 2015 deviennent caducs à compter de cette date.</p>"
    "<p>Cette caducité ne remet pas en vigueur le document d'urbanisme antérieur.</p>"
    "<p>À compter du 1er janvier 2016, le règlement national d'urbanisme mentionné aux articles L. 111-1 et L. 422-6 s'applique au territoire communal dont le plan d'occupation des sols est caduc.</p>",
    "Réécriture à droit constant : la réserve des régimes transitoires est placée en tête et les trois conséquences sont conservées dans leur ordre. Aucune réforme de fond ni nouvelle caducité liée au projet.",
    "Les dates du 31 décembre 2015 et du 1er janvier 2016, la réserve de L. 174-2 à L. 174-5 et les renvois à L. 111-1 et L. 422-6 sont conservés. Les premier et dernier alinéas gardent leur position pour le renvoi de L. 174-5. L. 174-6 prévoit distinctement le rétablissement d'un POS après annulation ou déclaration d'illégalité.")

add('L174-2',
    "<p>Les plans d'occupation des sols approuvés avant le 15 décembre 2000 demeurent provisoirement en vigueur si les conditions prévues aux articles L. 174-3 et L. 174-4 sont remplies, et dans la limite des durées fixées par ces articles.</p>"
    "<p>L'article L. 174-5 leur est applicable.</p>",
    "Réécriture à droit constant : la catégorie de plans est placée en sujet et les conditions et limites de durée sont distinguées. Les renvois de la source sont conservés malgré leur désajustement apparent. Aucune réforme de fond.",
    "Incohérence préexistante constatée dans le corpus : L. 174-2 renvoie à L. 174-4 pour des conditions et durées et à L. 174-5 pour le régime applicable, alors que L. 174-4, dans sa version du 26 mai 2026, contient le régime et les possibilités d'évolution des POS, et L. 174-5 fixe une transition jusqu'au 31 décembre 2020. Une coordination expresse de ces renvois est à déterminer ; aucun numéro n'est corrigé silencieusement. La date du 15 décembre 2000 est maintenue.")

add('L174-3',
    "<p>Une procédure de révision d'un plan d'occupation des sols engagée avant le 31 décembre 2015 peut être menée à terme selon les articles L. 123-1 et suivants, dans leur rédaction issue de la loi n° 2014-366 du 24 mars 2014 pour l'accès au logement et un urbanisme rénové. Cette faculté est subordonnée à l'achèvement de la procédure au plus tard le 26 mars 2017 ou, dans les communes d'outre-mer, le 26 septembre 2018. Les dispositions du plan d'occupation des sols demeurent en vigueur jusqu'à l'approbation du plan local d'urbanisme, sans dépasser la date limite applicable.</p>",
    "Réécriture à droit constant : la longue phrase est répartie entre la faculté d'achever la révision, son échéance et le maintien temporaire du POS. La référence à la date limite applicable explicite la distinction territoriale déjà énoncée. Aucune réforme de fond.",
    "Conserver le déclenchement avant le 31 décembre 2015, la référence historique à L. 123-1 et suivants dans la rédaction issue de la loi n° 2014-366 du 24 mars 2014, et les échéances distinctes du 26 mars 2017 et du 26 septembre 2018 pour les communes d'outre-mer. Ces dates échues ne sont ni reportées ni réouvertes ; le maintien cesse aussi lors de l'approbation du PLU si elle intervient plus tôt.")

add('L174-4',
    "<p>Les plans d'occupation des sols dont le présent chapitre prévoit le maintien provisoire en vigueur produisent les mêmes effets que les plans locaux d'urbanisme.</p>"
    "<p>Le régime juridique des plans locaux d'urbanisme défini au titre V du présent livre leur est applicable.</p>"
    "<p>L'article L. 123-1, dans sa rédaction antérieure au 15 décembre 2000, continue de leur être applicable.</p>"
    "<p>Ces plans peuvent faire l'objet :</p>"
    "<p>1° D'une modification, à condition qu'elle ne porte pas atteinte à l'économie générale du plan ;</p>"
    "<p>2° D'une mise en compatibilité, selon les modalités prévues aux articles L. 153-54 à L. 153-59.</p>"
    "<p>Si un plan d'occupation des sols a été approuvé avant le classement des carrières dans la nomenclature des installations classées, seules les dispositions de ce plan visant expressément les carrières sont opposables à leur ouverture.</p>",
    "Réécriture à droit constant : l'effet et le régime des POS sont énoncés plus directement, la condition de modification est rattachée à celle-ci et la règle spéciale des carrières est clarifiée. Les sept alinéas et les subdivisions 1° et 2° sont maintenus. Aucune réforme de fond.",
    "Maintenir le renvoi historique à L. 123-1 avant le 15 décembre 2000, les articles L. 153-54 à L. 153-59 et la limitation spéciale concernant les carrières. Selon la note source, le VI de l'article 1 de la loi n° 2025-1129 du 26 novembre 2025 fait entrer cette rédaction en vigueur six mois après la promulgation, soit le 26 mai 2026, et l'exclut pour les procédures d'évolution des SCoT ou des PLU en cours à cette date. Cette transition existante doit être conservée dans le dispositif d'application ; ce n'est pas la date de la réforme projetée. Coordination à contrôler avec L. 174-2, qui vise encore le présent article comme fixant des durées de maintien, alors qu'il en énonce le régime.")

add('L174-5',
    "<p>Les dates et délais fixés aux premier et dernier alinéas de l'article L. 174-1 ne s'appliquent pas aux plans d'occupation des sols en vigueur sur le territoire d'un établissement public de coopération intercommunale compétent en matière de plan local d'urbanisme ou de document d'urbanisme en tenant lieu, si cet établissement a engagé l'élaboration d'un plan local d'urbanisme intercommunal avant le 31 décembre 2015 et si ce plan est approuvé au plus tard le 31 décembre 2020.</p>"
    "<p>Si le plan local d'urbanisme intercommunal n'a pas été approuvé, ces dispositions cessent de s'appliquer à compter du 1er janvier 2021.</p>"
    "<p>Le premier alinéa s'applique aussi au territoire des anciennes communautés qui ont engagé la révision ou l'élaboration d'un plan local d'urbanisme intercommunal avant le 31 décembre 2015 et dont toutes les communes ont fusionné après l'engagement de ce plan. Dans ce cas, le plan local d'urbanisme, devenu communal, doit être approuvé au plus tard le 31 décembre 2020.</p>",
    "Réécriture à droit constant : la dérogation aux dates de caducité est placée en tête, ses conditions sont reliées explicitement et les règles de cessation et de fusion restent dans leurs alinéas. Aucune réforme de fond.",
    "Conserver les deux échéances du 31 décembre 2015 et du 31 décembre 2020, la cessation au 1er janvier 2021, le renvoi aux premier et dernier alinéas de L. 174-1 et l'extension aux anciennes communautés sous condition de fusion de toutes leurs communes. Les délais historiques ne sont pas prorogés. Voir le renvoi désajusté de L. 174-2 au présent article, signalé dans ses notes.")

add('L174-6',
    "<p>Lorsqu'elle intervient après le 31 décembre 2015, l'annulation ou la déclaration d'illégalité d'un plan local d'urbanisme, d'un document d'urbanisme en tenant lieu ou d'une carte communale peut remettre en vigueur le plan d'occupation des sols immédiatement antérieur, si elle entraîne la remise en application du document immédiatement antérieur en vertu de l'article L. 600-12.</p>"
    "<p>Ce plan d'occupation des sols redevient applicable pendant vingt-quatre mois à compter de la date de l'annulation ou de la déclaration d'illégalité. Pendant cette période, ce plan ne peut faire l'objet d'aucune procédure d'évolution.</p>"
    "<p>Si aucun plan local d'urbanisme ni aucune carte communale n'est exécutoire à l'issue de cette période, le règlement national d'urbanisme s'applique au territoire communal.</p>",
    "Réécriture à droit constant : les conditions du rétablissement sont remises dans l'ordre temporel, puis la durée et le régime à son terme sont formulés directement. Les trois alinéas sont maintenus. Aucune réforme de fond.",
    "La date postérieure au 31 décembre 2015, les vingt-quatre mois à compter de la décision et l'interdiction de toute procédure d'évolution sont conservés. L. 600-12, vérifié dans le corpus, comporte lui-même des réserves aux articles L. 600-12-1 et L. 442-14 ; le renvoi les laisse applicables. Ce délai de vingt-quatre mois est propre au rétablissement des POS : il ne constitue pas la voie de rénovation locative envisagée dans policy.json, qui appelle notamment la loi n° 89-462 hors des cinq codes.")

add('L175-1',
    "<p>I. - La procédure prévue à l'article L. 131-7 ne s'applique pas aux plans locaux d'urbanisme ou aux documents en tenant lieu applicables sur le territoire concerné par une procédure de révision ou d'élaboration d'un plan local d'urbanisme intercommunal engagée avant le 31 décembre 2015, à condition que ce plan intercommunal soit approuvé au plus tard le 31 décembre 2019.</p>"
    "<p>Si le plan local d'urbanisme intercommunal n'a pas été approuvé, le présent I cesse de s'appliquer à compter du 1er janvier 2020.</p>"
    "<p>Le présent I s'applique aussi au territoire des anciennes communautés qui ont engagé la révision ou l'élaboration d'un plan local d'urbanisme intercommunal avant le 31 décembre 2015 et dont toutes les communes ont fusionné après l'engagement de ce plan. Dans ce cas, le plan local d'urbanisme, devenu communal, doit être approuvé au plus tard le 31 décembre 2019.</p>"
    "<p>II. - Les dispositions du I s'appliquent également à la métropole de Lyon.</p>",
    "Réécriture à droit constant : le champ de l'exemption est exposé avant ses conditions, la cessation est formulée directement et l'accord grammatical de « ne s'applique » est rétabli. Les I et II et leurs alinéas sont conservés. Aucune réforme de fond.",
    "Sont conservés L. 131-7, l'engagement avant le 31 décembre 2015, l'approbation au plus tard le 31 décembre 2019, la cessation au 1er janvier 2020, les anciennes communautés et la métropole de Lyon. La note source se fonde sur l'article 7 de l'ordonnance n° 2020-745 du 17 juin 2020 : elle annonce l'application aux SCoT, PLU, documents en tenant lieu et cartes communales dont l'élaboration ou la révision est engagée à compter du 1er avril 2021. Cette indication postérieure aux échéances de l'article présente une discordance temporelle préexistante à contrôler ; aucune réouverture des délais n'est déduite de la note. Le renvoi à L. 131-7 est conservé malgré ses évolutions ultérieures, dont la version du 26 mai 2026 consultée dans le corpus.")

add('L210-1',
    "<p>Les droits de préemption institués par le présent titre sont exercés dans l'intérêt général pour réaliser des actions ou opérations répondant aux objets définis à l'article L. 300-1, ou pour constituer des réserves foncières permettant la réalisation de ces actions ou opérations d'aménagement. Sont exclus les objets visant à sauvegarder ou à mettre en valeur les espaces naturels, à préserver la qualité de la ressource en eau ou à permettre l'adaptation des territoires au recul du trait de côte.</p>"
    "<p>Pendant la durée d'application d'un arrêté préfectoral pris sur le fondement de l'article L. 302-9-1 du code de la construction et de l'habitation, le représentant de l'État dans le département exerce le droit de préemption si l'aliénation porte sur un bien ou un droit énuméré aux 1° à 4° de l'article L. 213-1 du présent code, affecté au logement ou destiné à être affecté à une opération ayant fait l'objet de la convention prévue à l'article L. 302-9-1 précité. Il peut déléguer ce droit : à un établissement public de coopération intercommunale à fiscalité propre ayant conclu une convention mentionnée au deuxième alinéa de l'article L. 301-5-1 du code de la construction et de l'habitation, au II de l'article L. 5217-2, au II de l'article L. 5218-2 ou au VI de l'article L. 5219-1 du code général des collectivités territoriales ; à la métropole de Lyon ayant conclu une convention mentionnée à l'article L. 3641-5 du code général des collectivités territoriales ; à un établissement public foncier créé en application des articles L. 321-1 ou L. 324-1 du présent code ; à l'office foncier de la Corse mentionné à l'article L. 4424-26-1 du code général des collectivités territoriales ; à une société d'économie mixte agréée mentionnée à l'article L. 481-1 du code de la construction et de l'habitation ; à un organisme d'habitations à loyer modéré prévu à l'article L. 411-2 du même code ; ou à un organisme agréé mentionné à l'article L. 365-2 du même code. Les biens acquis par préemption en application du présent alinéa doivent être utilisés pour réaliser des opérations d'aménagement ou de construction permettant d'atteindre les objectifs fixés dans le programme local de l'habitat ou déterminés en application du premier alinéa de l'article L. 302-8 du code de la construction et de l'habitation. Sur demande motivée de la collectivité territoriale initialement titulaire du droit de préemption et pour un bien précisément identifié, le représentant de l'État dans le département peut renoncer, pour lui-même, à exercer ce droit et autoriser cette collectivité, par arrêté motivé, à l'exercer pour ce seul bien. L'arrêté indique notamment le bien concerné et la finalité de la préemption. Si le bien concerné par cette renonciation relève de la compétence du représentant de l'État dans le département pour l'octroi des autorisations d'urbanisme et d'occupation du sol, en application du d de l'article L. 422-2 du présent code, l'arrêté peut autoriser la même collectivité territoriale à exercer cette compétence pour ce seul bien.</p>"
    "<p>Toute décision de préemption doit préciser l'objet pour lequel le droit est exercé. Toutefois, si la préemption vise à constituer des réserves foncières dans une zone d'aménagement différé, la décision peut renvoyer aux motivations générales de l'acte créant la zone.</p>"
    "<p>Lorsqu'une commune a délibéré pour définir le cadre des actions destinées à mener à bien un programme local de l'habitat ou, en l'absence d'un tel programme, un programme de construction de logements locatifs sociaux, la décision de préemption peut se référer à cette délibération, sauf si elle concerne un bien mentionné à l'article L. 211-4. Il en est de même si la commune a délibéré pour délimiter des périmètres déterminés dans lesquels elle décide d'intervenir afin de les aménager et d'améliorer leur qualité urbaine.</p>",
    "Réécriture à droit constant : les finalités et exclusions sont séparées dans le premier alinéa ; les destinataires de la délégation sont distingués par des points-virgules ; les conditions de renonciation, d'autorisation limitée à un bien et de motivation sont rendues plus directes. Les quatre alinéas, notamment le deuxième visé par d'autres articles, restent en place. Aucune réforme de fond et aucune suppression des obligations de logement social.",
    "Conserver tous les délégataires et leurs conditions conventionnelles, les 1° à 4° de L. 213-1, le d de L. 422-2, les renvois au CCH et au CGCT, la durée de l'arrêté et l'affectation obligatoire des biens aux objectifs d'habitat. La demande motivée de la collectivité, l'arrêté motivé et son champ limité à un seul bien sont maintenus. L'exception L. 211-4 demeure au quatrième alinéa. Articulation préexistante à contrôler avec L. 211-1-1 : les secteurs de nature en ville ou de renaturation y sont admis alors que le premier alinéa du présent article exclut certains objets environnementaux ; la définition d'un périmètre ne doit pas être confondue avec la justification de la finalité d'une préemption. Aucune convention locale ne vaut dispense des objectifs de logement social.")

add('L210-2',
    "<p>La commune peut exercer son droit de préemption en cas de vente d'un immeuble à usage d'habitation, afin d'assurer le maintien des locataires dans les lieux.</p>",
    "Réécriture à droit constant : la commune est placée en sujet et la faculté de préemption est directement reliée à la vente et au maintien des locataires dans les lieux. Aucune réforme de fond.",
    "La faculté reste limitée à la vente d'un immeuble à usage d'habitation et ne crée pas un nouveau droit de préemption autonome. Les mesures de traitement judiciaire des impayés de policy.json ne sont pas introduites dans cet article.")

add('L211-1',
    "<p>Les communes dotées d'un plan d'occupation des sols rendu public ou d'un plan local d'urbanisme approuvé peuvent instituer, par délibération, un droit de préemption urbain : sur tout ou partie des zones urbaines et des zones d'urbanisation future délimitées par ce plan ; dans les périmètres de protection rapprochée des prélèvements d'eau destinée à l'alimentation des collectivités humaines définis en application de l'article L. 1321-2 du code de la santé publique ; dans les zones et secteurs définis par un plan de prévention des risques technologiques en application de l'article L. 515-16 du code de l'environnement ; dans les zones soumises aux servitudes prévues au II de l'article L. 211-12 du même code ; sur tout ou partie des espaces urbains et des secteurs occupés par une urbanisation diffuse délimités conformément aux articles L. 5112-1 et L. 5112-2 du code général de la propriété des personnes publiques ; ainsi que sur tout ou partie de leur territoire couvert par un plan de sauvegarde et de mise en valeur rendu public ou approuvé en application de l'article L. 313-1 du présent code. Ce droit peut être institué lorsqu'aucune zone d'aménagement différé ni aucun périmètre provisoire de zone d'aménagement différé n'a été créé sur les territoires concernés.</p>"
    "<p>Dans les communes dotées d'une carte communale approuvée, le conseil municipal peut instituer un droit de préemption dans un ou plusieurs périmètres délimités par cette carte, afin de réaliser un équipement ou une opération d'aménagement. Pour chaque périmètre, la délibération précise l'équipement ou l'opération projetée.</p>"
    "<p>La commune est titulaire de ce droit de préemption. Le conseil municipal peut le supprimer sur tout ou partie des zones concernées, puis le rétablir dans les mêmes conditions. Toutefois, dans le cas prévu au deuxième alinéa de l'article L. 210-1, le représentant de l'État dans le département peut instituer ou rétablir ce droit par arrêté. Dans les parties actuellement urbanisées des communes dont le plan d'occupation des sols est devenu caduc en application de l'article L. 174-1, le droit de préemption prévu au deuxième alinéa de l'article L. 210-1 est maintenu.</p>"
    "<p>Après l'autorisation d'un lotissement ou la création d'une zone d'aménagement concerté, la commune peut exclure du droit de préemption urbain la vente des lots issus de ce lotissement ou les cessions de terrains par la personne chargée de l'aménagement de cette zone. La délibération du conseil municipal prononçant cette exclusion est valable pendant cinq ans à compter du jour où elle devient exécutoire.</p>"
    "<p>Par dérogation au premier alinéa de l'article L. 210-1, le droit de préemption institué selon le présent article peut être exercé pour relocaliser des activités industrielles, commerciales, artisanales ou de services. Il peut également être exercé pour reloger les occupants définitivement évincés d'un bien à usage d'habitation ou mixte en raison de travaux nécessaires à une opération d'aménagement définie au livre III du présent code.</p>",
    "Réécriture à droit constant : les périmètres du premier alinéa sont distingués par la ponctuation, le titulaire du droit et les compétences de suppression ou de rétablissement sont explicités, et les deux finalités dérogatoires du dernier alinéa sont séparées en phrases. Les cinq alinéas sont maintenus. Aucune réforme de fond.",
    "Maintenir tous les périmètres, les conditions tenant au document d'urbanisme et à l'absence de ZAD ou de périmètre provisoire, le II de L. 211-12 et les autres renvois. Le cas préfectoral reste rattaché au deuxième alinéa de L. 210-1, conservé à sa place. La durée de cinq ans part du caractère exécutoire de la délibération. La dérogation finale conserve l'éviction définitive et son lien avec des travaux nécessaires aux opérations du livre III. La mention des POS rendus publics est historique et ne les soustrait pas aux règles de caducité du chapitre L. 174.")

add('L211-1-1',
    "<p>Par délibération motivée, l'autorité compétente peut délimiter, au sein du plan local d'urbanisme, du document en tenant lieu ou de la carte communale, des secteurs prioritaires à mobiliser présentant un potentiel foncier majeur pour favoriser l'atteinte des objectifs de lutte contre l'artificialisation des sols prévus en application de l'article L. 151-5. Le droit de préemption urbain prévu au présent chapitre est institué dans ces secteurs. Les articles L. 210-1 et L. 213-1 à L. 213-18 s'appliquent également à ce droit.</p>"
    "<p>Ces secteurs prioritaires peuvent notamment couvrir :</p>"
    "<p>1° Des terrains qui contribuent à préserver ou à restaurer la nature en ville, notamment des surfaces végétalisées ou naturelles situées dans les espaces urbanisés ;</p>"
    "<p>2° Des zones à fort potentiel de renaturation, en particulier pour préserver ou restaurer les continuités écologiques. Ces zones peuvent notamment correspondre aux zones préférentielles pour la renaturation identifiées dans le schéma de cohérence territoriale, mentionnées à l'article L. 141-10 ;</p>"
    "<p>3° Des terrains pouvant contribuer au renouvellement urbain, à l'optimisation de la densité des espaces urbanisés ou à la réhabilitation des friches mentionnées à l'article L. 111-26.</p>",
    "Réécriture à droit constant : la faculté de délimitation, l'institution du droit et les règles qui s'y appliquent sont réparties en phrases distinctes dans le premier alinéa. Les exemples et les subdivisions 1° à 3° sont conservés, avec une phrase plus courte au 2°. Aucune réforme de fond ; les secteurs ne sont pas transformés en autorisations de construire.",
    "Conserver le caractère motivé de la délibération, le potentiel foncier majeur, les objectifs de L. 151-5, les trois documents de délimitation et les renvois à L. 210-1, L. 213-1 à L. 213-18, L. 141-10 et L. 111-26. Le caractère non exhaustif de la liste est maintenu. Articulation à contrôler avec l'exclusion de certains objets environnementaux au premier alinéa de L. 210-1, déjà présente dans la source. Les enveloppes de densification de coordination.json relèvent de L. 151-4 et L. 151-26, sans suppression ici des objectifs de renaturation ou de lutte contre l'artificialisation.")

add('L211-2',
    "<p>Une commune peut déléguer tout ou partie des compétences que lui attribue le présent chapitre à l'établissement public de coopération intercommunale dont elle est membre, si cet établissement a vocation à les exercer et donne son accord.</p>"
    "<p>Toutefois, la compétence en matière de plan local d'urbanisme d'un établissement public de coopération intercommunale à fiscalité propre, d'un établissement public territorial créé en application de l'article L. 5219-2 du code général des collectivités territoriales ou de la métropole de Lyon entraîne de plein droit sa compétence en matière de droit de préemption urbain. La métropole du Grand Paris est compétente de plein droit en matière de droit de préemption urbain dans les périmètres fixés par son conseil pour mettre en œuvre les opérations d'aménagement d'intérêt métropolitain mentionnées à l'article L. 5219-1 du même code. Dans ces périmètres, les aliénations nécessaires à la réalisation des opérations mentionnées au même article L. 5219-1 ne sont plus soumises aux droits de préemption urbains de la commune de Paris ni des établissements publics territoriaux créés en application de l'article L. 5219-2 du même code.</p>"
    "<p>Le titulaire du droit de préemption urbain peut le déléguer : à une société d'économie mixte agréée mentionnée à l'article L. 481-1 du code de la construction et de l'habitation ; à un organisme d'habitations à loyer modéré prévu à l'article L. 411-2 du même code ; à un organisme de foncier solidaire mentionné à l'article L. 329-1 dudit code, pour les biens nécessaires à son objet principal ; ou à un organisme agréé mentionné à l'article L. 365-2 du même code. L'organe délibérant de ces organismes peut déléguer l'exercice de ce droit dans les conditions définies par décret en Conseil d'État. Par dérogation à l'article L. 213-11 du présent code, les biens acquis par préemption en application du présent alinéa ne peuvent être utilisés que pour réaliser des opérations d'aménagement ou de construction permettant d'atteindre les objectifs fixés dans le programme local de l'habitat ou déterminés en application du premier alinéa de l'article L. 302-8 du code de la construction et de l'habitation, ainsi que pour réaliser des opérations programmées d'amélioration de l'habitat prévues à l'article L. 303-1 du même code, des plans de sauvegarde prévus à l'article L. 615-1 du même code ou des opérations de requalification de copropriétés dégradées prévues à l'article L. 741-1 du même code.</p>"
    "<p>Dans le périmètre d'une grande opération d'urbanisme au sens de l'article L. 312-3 du présent code, la collectivité territoriale ou l'établissement public cocontractant mentionné au même article L. 312-3 exerce le droit de préemption prévu au présent chapitre. Cette collectivité ou cet établissement peut en déléguer l'exercice à un établissement public ayant vocation à l'exercer ou au concessionnaire d'une opération d'aménagement.</p>",
    "Réécriture à droit constant : l'accord nécessaire à la délégation communale est rendu explicite ; les compétences de plein droit, les bénéficiaires des délégations et les usages autorisés des biens sont énoncés plus directement. Les quatre alinéas et les restrictions propres aux organismes et aux grandes opérations d'urbanisme sont maintenus. Aucune réforme de fond.",
    "Incohérence de renvoi préexistante : au troisième alinéa, la source vise les organismes de foncier solidaire à L. 329-1 « dudit code », dont l'antécédent est le CCH. Dans le corpus fourni, L. 329-1 définissant ces organismes appartient au code de l'urbanisme et aucun L. 329-1 ne figure dans le CCH. Le libellé de rattachement de la source est conservé et appelle une correction expresse du code visé. Maintenir la limitation aux biens nécessaires à l'objet principal des OFS, l'usage exclusif des biens acquis, la dérogation à L. 213-11, le premier alinéa de L. 302-8 et tous les autres renvois. Les droits de la commune de Paris et des établissements publics territoriaux sont écartés uniquement pour les aliénations nécessaires aux opérations métropolitaines dans les périmètres identifiés ; aucune extinction générale n'est ajoutée.")

assert len(source) == len(drafts) == 24
answer = []
for article in source:
    proposed, reason, notes = drafts[article['number']]
    entry = {key: article[key] for key in ('code_id', 'source_id', 'source_sha256', 'number')}
    entry.update(proposed_xml=proposed, reason=reason, review_notes=notes, status='rewrite_draft')
    answer.append(entry)
Path('answer.json').write_text(json.dumps(answer, ensure_ascii=False, indent=2) + '\n')
